//! Sprite loading. All art comes from `assets/sprites/`, generated by
//! `tools/gen_sprites.py` — regenerate there, never edit PNGs.

use anyhow::{Context, Result};
use macroquad::audio::{Sound, load_sound};
use macroquad::prelude::{FilterMode, Rect, Texture2D, load_texture};
use oxide_sim::{Faction, UnitKind};

/// Every sprite the shell draws, as regions of ONE texture.
///
/// A single atlas means macroquad batches the entire world into a handful
/// of draw calls; the previous texture-per-sprite scheme flushed the batch
/// on nearly every tile and halved the framerate zoomed out.
pub struct Sprites {
    texture: Texture2D,
    ground: [Rect; 6],
    rock: [Rect; 4],
    /// Skyline row of a range, indexed `w_conn * 4 + e_conn * 2 + variant`.
    peak_sky: [Rect; 8],
    peak_lone: [Rect; 2],
    peak_body: [Rect; 2],
    turret_barrel: [Rect; 2],
    rock_skirt: Rect,
    decals: [Rect; 4],
    scrap_full: Rect,
    scrap_mid: Rect,
    scrap_low: Rect,
    scrap_rich: Rect,
    muzzle_flash: Rect,
    scorch: Rect,
    wreck_pile: Rect,
    air_shadow: Rect,
    burst: Rect,
    foundry: [Rect; 2],
    turret: [Rect; 2],
    fabricator: [Rect; 2],
    flak_turret: [Rect; 2],
    bastion: [Rect; 2],
    array: [Rect; 2],
    reclaimer: [Rect; 2],
    harvester: [Rect; 2],
    harvester_scoop: [[Rect; 2]; 2],
    scaffold: [Rect; 2],
    debris: [Rect; 3],
    scuttler: [Rect; 2],
    lancer: [Rect; 2],
    sentinel: [Rect; 2],
    bombard: [Rect; 2],
    flakhound: [Rect; 2],
    stinger: [Rect; 2],
    buzzard: [Rect; 2],
    darter: [Rect; 2],
    talon: [Rect; 2],
    wisp: [Rect; 2],
}

fn faction_index(faction: Faction) -> usize {
    match faction {
        Faction::Ferrous => 0,
        Faction::Cupric => 1,
    }
}

/// Where game data lives. A macOS .app bundle keeps it in
/// Contents/Resources beside Contents/MacOS/<exe>; development runs
/// from the workspace root. Resolved once by probing for the atlas —
/// the one file no build ships without.
pub fn resource_root() -> std::path::PathBuf {
    if let Ok(exe) = std::env::current_exe()
        && let Some(dir) = exe.parent()
    {
        let bundled = dir.join("../Resources");
        if bundled.join("assets/sprites/atlas.png").exists() {
            return bundled;
        }
    }
    std::path::PathBuf::from(".")
}

/// A resource path as a string macroquad's loaders accept.
pub fn resource(rel: &str) -> String {
    resource_root().join(rel).to_string_lossy().into_owned()
}

impl Sprites {
    /// Loads the atlas up front; a missing or incomplete atlas is a
    /// startup error, not a mid-game pop.
    pub async fn load() -> Result<Self> {
        let texture = load_texture(&resource("assets/sprites/atlas.png"))
            .await
            .context("loading assets/sprites/atlas.png (run from the workspace root)")?;
        texture.set_filter(FilterMode::Linear);
        let manifest = macroquad::file::load_string(&resource("assets/sprites/atlas.json"))
            .await
            .context("loading assets/sprites/atlas.json")?;
        let rects: std::collections::HashMap<String, [f32; 4]> =
            serde_json::from_str(&manifest).context("parsing atlas manifest")?;
        let rect = |name: &str| -> Result<Rect> {
            let [x, y, w, h] = rects
                .get(name)
                .copied()
                .with_context(|| format!("sprite {name:?} missing from atlas"))?;
            Ok(Rect::new(x, y, w, h))
        };
        Ok(Self {
            texture,
            ground: [
                rect("ground_0")?,
                rect("ground_1")?,
                rect("ground_2")?,
                rect("ground_3")?,
                rect("ground_4")?,
                rect("ground_5")?,
            ],
            rock: [
                rect("rock_0")?,
                rect("rock_1")?,
                rect("rock_2")?,
                rect("rock_3")?,
            ],
            peak_sky: [
                rect("peak_sky_00_0")?,
                rect("peak_sky_00_1")?,
                rect("peak_sky_01_0")?,
                rect("peak_sky_01_1")?,
                rect("peak_sky_10_0")?,
                rect("peak_sky_10_1")?,
                rect("peak_sky_11_0")?,
                rect("peak_sky_11_1")?,
            ],
            peak_lone: [rect("peak_lone_0")?, rect("peak_lone_1")?],
            peak_body: [rect("peak_body_0")?, rect("peak_body_1")?],
            turret_barrel: [
                rect("turret_barrel_ferrous")?,
                rect("turret_barrel_cupric")?,
            ],
            rock_skirt: rect("rock_skirt")?,
            decals: [
                rect("decal_crack")?,
                rect("decal_plate")?,
                rect("decal_stain")?,
                rect("decal_wreck")?,
            ],
            scrap_full: rect("scrap_full")?,
            scrap_mid: rect("scrap_mid")?,
            scrap_low: rect("scrap_low")?,
            scrap_rich: rect("scrap_rich")?,
            muzzle_flash: rect("muzzle_flash")?,
            scorch: rect("scorch")?,
            wreck_pile: rect("wreck_pile")?,
            air_shadow: rect("air_shadow")?,
            burst: rect("burst")?,
            foundry: [rect("foundry_ferrous")?, rect("foundry_cupric")?],
            turret: [rect("turret_ferrous")?, rect("turret_cupric")?],
            fabricator: [rect("fabricator_ferrous")?, rect("fabricator_cupric")?],
            flak_turret: [rect("flak_turret_ferrous")?, rect("flak_turret_cupric")?],
            bastion: [rect("bastion_ferrous")?, rect("bastion_cupric")?],
            array: [rect("array_ferrous")?, rect("array_cupric")?],
            reclaimer: [rect("reclaimer_ferrous")?, rect("reclaimer_cupric")?],
            harvester: [rect("harvester_ferrous")?, rect("harvester_cupric")?],
            harvester_scoop: [
                [
                    rect("harvester_ferrous_scoop1")?,
                    rect("harvester_cupric_scoop1")?,
                ],
                [
                    rect("harvester_ferrous_scoop2")?,
                    rect("harvester_cupric_scoop2")?,
                ],
            ],
            scaffold: [rect("scaffold_dense")?, rect("scaffold_sparse")?],
            debris: [rect("debris_0")?, rect("debris_1")?, rect("debris_2")?],
            scuttler: [rect("scuttler_ferrous")?, rect("scuttler_cupric")?],
            lancer: [rect("lancer_ferrous")?, rect("lancer_cupric")?],
            sentinel: [rect("sentinel_ferrous")?, rect("sentinel_cupric")?],
            bombard: [rect("bombard_ferrous")?, rect("bombard_cupric")?],
            flakhound: [rect("flakhound_ferrous")?, rect("flakhound_cupric")?],
            stinger: [rect("stinger_ferrous")?, rect("stinger_cupric")?],
            buzzard: [rect("buzzard_ferrous")?, rect("buzzard_cupric")?],
            darter: [rect("darter_ferrous")?, rect("darter_cupric")?],
            talon: [rect("talon_ferrous")?, rect("talon_cupric")?],
            wisp: [rect("wisp_ferrous")?, rect("wisp_cupric")?],
        })
    }

    /// The one texture every sprite lives in.
    pub fn texture(&self) -> &Texture2D {
        &self.texture
    }

    /// A ground variant's atlas region.
    pub fn ground(&self, variant: usize) -> Rect {
        self.ground[variant % self.ground.len()]
    }

    /// A rock variant's atlas region.
    pub fn rock(&self, variant: usize) -> Rect {
        self.rock[variant % self.rock.len()]
    }

    /// The turret's rotating gun, per faction.
    pub fn turret_barrel(&self, faction: oxide_sim::Faction) -> Rect {
        self.turret_barrel[match faction {
            oxide_sim::Faction::Ferrous => 0,
            oxide_sim::Faction::Cupric => 1,
        }]
    }

    /// The skyline row of a mountain range: crests against open sky.
    /// `w_conn`/`e_conn` say whether the ridge continues into the
    /// neighboring tile on that side; connected sides meet the edge at
    /// a fixed height so adjacent tiles join without a seam.
    pub fn peak_sky(&self, w_conn: bool, e_conn: bool, variant: usize) -> Rect {
        self.peak_sky[(w_conn as usize) * 4 + (e_conn as usize) * 2 + (variant % 2)]
    }

    /// A single standing peak with inset feet.
    pub fn peak_lone(&self, variant: usize) -> Rect {
        self.peak_lone[variant % self.peak_lone.len()]
    }

    /// Interior of a mountain wall: solid rock, seamless on every edge.
    pub fn peak_body(&self, variant: usize) -> Rect {
        self.peak_body[variant % self.peak_body.len()]
    }

    /// The soft shadow a rock casts on a neighboring ground tile
    /// (authored falling from the top edge; rotate toward the rock).
    pub fn rock_skirt(&self) -> Rect {
        self.rock_skirt
    }

    /// A ground decal's atlas region.
    pub fn decal(&self, variant: usize) -> Rect {
        self.decals[variant % self.decals.len()]
    }

    /// The scrap sprite region for a remaining amount: anything above a
    /// standard node renders as the rich pile, then thirds of standard.
    pub fn scrap(&self, amount: u32, standard_amount: u32) -> Rect {
        if amount > standard_amount {
            self.scrap_rich
        } else if amount * 3 > standard_amount * 2 {
            self.scrap_full
        } else if amount * 3 > standard_amount {
            self.scrap_mid
        } else {
            self.scrap_low
        }
    }

    /// The muzzle-flash atlas region.
    pub fn muzzle_flash(&self) -> Rect {
        self.muzzle_flash
    }

    /// The building-death scorch decal region.
    pub fn scorch(&self) -> Rect {
        self.scorch
    }

    /// A wreck salvage pile on open ground.
    pub fn wreck_pile(&self) -> Rect {
        self.wreck_pile
    }

    /// The soft shadow a flyer casts on the ground.
    pub fn air_shadow(&self) -> Rect {
        self.air_shadow
    }

    /// The splash-detonation frame.
    pub fn burst(&self) -> Rect {
        self.burst
    }

    /// The building sprite region for a kind and faction.
    pub fn building(&self, kind: oxide_sim::BuildingKind, faction: Faction) -> Rect {
        let f = faction_index(faction);
        match kind {
            oxide_sim::BuildingKind::Foundry => self.foundry[f],
            oxide_sim::BuildingKind::Turret => self.turret[f],
            oxide_sim::BuildingKind::Fabricator => self.fabricator[f],
            oxide_sim::BuildingKind::FlakTurret => self.flak_turret[f],
            oxide_sim::BuildingKind::Bastion => self.bastion[f],
            oxide_sim::BuildingKind::Array => self.array[f],
            oxide_sim::BuildingKind::Reclaimer => self.reclaimer[f],
        }
    }

    /// A working harvester's scoop-cycle frame: 0 is the travel pose,
    /// 1-2 the dig. Values past 2 are the caller's cycle math leaking.
    pub fn harvester_working(&self, faction: Faction, frame: usize) -> Rect {
        let f = faction_index(faction);
        match frame {
            0 => self.harvester[f],
            1 => self.harvester_scoop[0][f],
            _ => self.harvester_scoop[1][f],
        }
    }

    /// The construction lattice: dense early, sparse near completion.
    pub fn scaffold(&self, dense: bool) -> Rect {
        self.scaffold[if dense { 0 } else { 1 }]
    }

    /// A death-scatter hull shard.
    pub fn debris(&self, variant: usize) -> Rect {
        self.debris[variant % 3]
    }

    /// The unit sprite region for a kind and faction.
    pub fn unit(&self, kind: UnitKind, faction: Faction) -> Rect {
        let f = faction_index(faction);
        match kind {
            UnitKind::Harvester => self.harvester[f],
            UnitKind::Sentinel => self.sentinel[f],
            UnitKind::Scuttler => self.scuttler[f],
            UnitKind::Lancer => self.lancer[f],
            UnitKind::Bombard => self.bombard[f],
            UnitKind::Flakhound => self.flakhound[f],
            UnitKind::Stinger => self.stinger[f],
            UnitKind::Buzzard => self.buzzard[f],
            UnitKind::Darter => self.darter[f],
            UnitKind::Talon => self.talon[f],
            UnitKind::Wisp => self.wisp[f],
        }
    }
}

/// Every clip the shell plays. Generated by `tools/gen_sounds.py`.
pub struct Sounds {
    /// An attack landing.
    pub laser: Sound,
    /// A Lancer's rail shot.
    pub rail_fire: Sound,
    /// A unit popping.
    pub unit_death: Sound,
    /// A building coming down.
    pub building_boom: Sound,
    /// Your harvester delivering.
    pub deposit: Sound,
    /// Your Foundry finishing a unit.
    pub train_done: Sound,
    /// Menu activation.
    pub click: Sound,
    /// An order was refused.
    pub denied: Sound,
    /// You won.
    pub victory: Sound,
    /// You didn't.
    pub defeat: Sound,
    /// Flak bursting against the sky.
    pub flak: Sound,
    /// An artillery shell landing.
    pub artillery_boom: Sound,
    /// The gun speaking (the boom belongs to the impact).
    pub artillery_launch: Sound,
    /// Order acknowledged.
    pub ack: Sound,
    /// The zap's lower sibling, alternated per shot.
    pub laser2: Sound,
}

async fn clip(name: &str) -> Result<Sound> {
    let path = resource(&format!("assets/sounds/{name}.wav"));
    load_sound(&path)
        .await
        .with_context(|| format!("loading {path} (run from the workspace root)"))
}

impl Sounds {
    /// Loads every clip up front, like [`Sprites::load`].
    pub async fn load() -> Result<Self> {
        Ok(Self {
            laser: clip("laser").await?,
            rail_fire: clip("rail_fire").await?,
            unit_death: clip("unit_death").await?,
            building_boom: clip("building_boom").await?,
            deposit: clip("deposit").await?,
            train_done: clip("train_done").await?,
            click: clip("click").await?,
            denied: clip("denied").await?,
            victory: clip("victory").await?,
            defeat: clip("defeat").await?,
            flak: clip("flak").await?,
            artillery_boom: clip("artillery_boom").await?,
            artillery_launch: clip("artillery_launch").await?,
            ack: clip("ack").await?,
            laser2: clip("laser2").await?,
        })
    }
}
